  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser is a clear, consequential invention that created a new route to compact, tunable mid-infrared and terahertz sources.",
        "attribution": "Cho and Capasso established the design and device program; Faist was central to the first realization. The proposed trio reflects the conceptual and experimental work.",
        "maturity": "The device principle has been demonstrated over decades and enabled a broad body of spectroscopy and sensing.",
        "uncertainties": [
          "The relative credit for the original design and first working device should be checked against the early publication and patent record."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Kam-Biu Luk",
        "Soo-Bong Kim",
        "Yifang Wang"
      ],
      "assessment": {
        "nobel_worthiness": "Measuring a nonzero theta-13 established a crucial parameter of neutrino mixing and opened the way to testing CP violation in the lepton sector.",
        "attribution": "Luk and Wang led important Daya Bay work, while Kim represents the independent RENO measurement. Credit should follow the original experimental leadership and the independent confirmation.",
        "maturity": "The result is robust, with consistent measurements from multiple reactor experiments.",
        "uncertainties": [
          "A prize would need to distinguish the discovery from the much larger collaborations and account for the parallel Daya Bay, RENO, and Double Chooz results."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube's detection of high-energy astrophysical neutrinos opened a new observational channel on the universe and established neutrino astronomy beyond the solar and atmospheric sources.",
        "attribution": "Halzen was the leading scientific architect and advocate for the detector. A single-person citation is plausible for the conception and sustained leadership, though the discovery depended on a large collaboration.",
        "maturity": "The astrophysical flux is supported by multiple analyses and source evidence has continued to develop.",
        "uncertainties": [
          "The balance between credit for conceiving the observatory and the collaboration's construction, operation, and discovery work requires careful review."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Hideo Hosono",
        "Xianhui Chen",
        "Zhongxian Zhao"
      ],
      "assessment": {
        "nobel_worthiness": "The discovery of iron-based high-temperature superconductors revealed an unexpected family of superconductors and reshaped research on unconventional pairing.",
        "attribution": "Hosono's original report of superconductivity in iron-based compounds is the defining discovery. Chen and Zhao made important early independent discoveries and demonstrations in related compounds.",
        "maturity": "The materials and superconducting phase diagrams have been studied for many years, though the mechanism remains unsettled.",
        "uncertainties": [
          "The field's rapid, parallel early discoveries make the boundaries between original discovery, confirmation, and expansion of the material family important."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Michel Della Negra",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The ATLAS and CMS detectors enabled the Higgs-boson discovery through an exceptionally demanding, independently confirmed experimental program.",
        "attribution": "These three leaders represent the conception and construction of the two experiments. The case is for detector invention and leadership, not a claim that a few individuals performed a collaboration-wide discovery alone.",
        "maturity": "The Higgs boson is firmly established and its properties continue to be measured with improving precision.",
        "uncertainties": [
          "The Nobel format cannot recognize the full detector teams, and the distinction between detector enabling work and the discovery itself needs a defensible basis."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Peter F. Moulton",
        "Ursula Keller",
        "Wilson Sibbett"
      ],
      "assessment": {
        "nobel_worthiness": "Titanium-sapphire lasers combined with reliable passive mode-locking made practical femtosecond sources broadly useful and transformed ultrafast science.",
        "attribution": "Moulton developed the key gain medium; Keller and Sibbett made foundational contributions to practical mode-locking and ultrashort-pulse operation.",
        "maturity": "The laser platform and its scientific impact have been established for decades.",
        "uncertainties": [
          "This bundles distinct material and mode-locking advances; the most original and prize-defining contributions should be specified."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precision mapping of the cosmic microwave background made cosmological parameters substantially more secure and established a detailed model of the early universe.",
        "attribution": "Bennett led the mission, Page contributed key experimental leadership, and Spergel helped establish the cosmological interpretation. Credit must be distinguished from COBE's pioneering measurements.",
        "maturity": "The maps and cosmological results have been extensively checked and extended by later observations.",
        "uncertainties": [
          "The boundary between WMAP's precision advance and the foundational COBE discovery is a central attribution question."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Qi-Kun Xue"
      ],
      "assessment": {
        "nobel_worthiness": "Topological insulators revealed a new class of electronic phases, and the quantum anomalous Hall effect demonstrated a striking transport consequence without an applied magnetic field.",
        "attribution": "Kane and Mele supplied foundational theory; Xue led important epitaxial growth and experimental realization of the quantum anomalous Hall effect.",
        "maturity": "Topological phases are firmly established, while the experimental regimes and materials continue to develop.",
        "uncertainties": [
          "The candidate combines a broad discovery with a particular realization, so the scope and credit allocation need sharper definition."
        ]
      }
    }
  ]
}
